  "inlineSchema": "// prisma/schema.prisma\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../app/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n/// ---------- Canonical I Ching content ----------\nmodel Trigram {\n  id      Int     @id // 1..8 (QIAN,KUN,ZHEN,KAN,GEN,XUN,LI,DUI)\n  key     String  @unique\n  name    String  @map(\"nameHr\")\n  meaning String?\n\n  upperOf Hexagram[] @relation(\"hex_upper\")\n  lowerOf Hexagram[] @relation(\"hex_lower\")\n}\n\nmodel Hexagram {\n  id        Int      @id\n  key       String   @unique\n  slug      String   @unique\n  name      String   @map(\"nameHr\")\n  judgment  String   @map(\"judgmentHr\")\n  imageText String?  @map(\"imageTextHr\")\n  comment   String?  @map(\"commentHr\")\n  footnote  String?  @map(\"footnoteHr\")\n  tags      String[]\n\n  upperTrigramId Int\n  lowerTrigramId Int\n  upperTrigram   Trigram @relation(\"hex_upper\", fields: [upperTrigramId], references: [id])\n  lowerTrigram   Trigram @relation(\"hex_lower\", fields: [lowerTrigramId], references: [id])\n\n  lines Line[]\n\n  baseForReadings   Reading[] @relation(\"reading_base_hex\")\n  resultForReadings Reading[] @relation(\"reading_result_hex\")\n\n  @@index([slug])\n}\n\nmodel Line {\n  id         Int      @id @default(autoincrement())\n  hexagramId Int\n  number     Int // 1 (bottom) .. 6 (top)\n  text       String   @map(\"textHr\")\n  Hexagram   Hexagram @relation(fields: [hexagramId], references: [id])\n\n  @@unique([hexagramId, number])\n  @@index([hexagramId])\n}\n\n/// Keep original JSON/text you typed (for provenance/versioning)\nmodel ContentSource {\n  id         String   @id @default(cuid())\n  key        String   @unique\n  payload    Json\n  version    String\n  importedAt DateTime @default(now())\n}\n\n/// ---------- Auth.js v5 compatible ----------\nmodel User {\n  id        String   @id @default(cuid())\n  name      String?\n  email     String?  @unique\n  image     String?\n  createdAt DateTime @default(now())\n\n  readings  Reading[]\n  chats     ChatSession[]\n  favorites Favorite[]\n  journal   JournalEntry[]\n\n  accounts Account[]\n  sessions Session[]\n}\n\nmodel Account {\n  id                String  @id @default(cuid())\n  userId            String\n  type              String\n  provider          String\n  providerAccountId String\n  refresh_token     String? @db.Text\n  access_token      String? @db.Text\n  expires_at        Int?\n  token_type        String?\n  scope             String?\n  id_token          String? @db.Text\n  session_state     String?\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([provider, providerAccountId])\n}\n\nmodel Session {\n  id           String   @id @default(cuid())\n  sessionToken String   @unique\n  userId       String\n  expires      DateTime\n  user         User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\nmodel VerificationToken {\n  identifier String\n  token      String   @unique\n  expires    DateTime\n\n  @@unique([identifier, token])\n}\n\n/// ---------- App domain (readings, chat, share) ----------\nmodel Reading {\n  id        String   @id @default(cuid())\n  userId    String?\n  createdAt DateTime @default(now())\n\n  method           String // \"3_coins\" | \"manual\"\n  seed             String? // optional reproducibility\n  tossesJson       Json // raw coin flips / line objects\n  movingLines      Int[] // e.g., [2,5]\n  baseHexagramId   Int\n  resultHexagramId Int\n  question         String?\n  notes            String?\n\n  User           User?         @relation(fields: [userId], references: [id], onDelete: SetNull)\n  baseHexagram   Hexagram      @relation(\"reading_base_hex\", fields: [baseHexagramId], references: [id])\n  resultHexagram Hexagram      @relation(\"reading_result_hex\", fields: [resultHexagramId], references: [id])\n  chats          ChatSession[]\n  shares         ShareLink[]\n  favorites      Favorite[]\n\n  @@index([userId, createdAt])\n  @@index([baseHexagramId])\n  @@index([resultHexagramId])\n}\n\nmodel ChatSession {\n  id        String   @id @default(cuid())\n  userId    String?\n  readingId String\n  createdAt DateTime @default(now())\n\n  User     User?         @relation(fields: [userId], references: [id], onDelete: SetNull)\n  Reading  Reading       @relation(fields: [readingId], references: [id], onDelete: Cascade)\n  messages ChatMessage[]\n\n  @@index([readingId])\n  @@index([userId, createdAt])\n}\n\nmodel ChatMessage {\n  id        String   @id @default(cuid())\n  sessionId String\n  role      String // \"user\" | \"assistant\" | \"system\"\n  content   String\n  createdAt DateTime @default(now())\n\n  Session ChatSession @relation(fields: [sessionId], references: [id], onDelete: Cascade)\n\n  @@index([sessionId, createdAt])\n}\n\nmodel ShareLink {\n  id        String    @id @default(cuid())\n  readingId String\n  token     String    @unique\n  createdAt DateTime  @default(now())\n  expiresAt DateTime?\n\n  Reading Reading @relation(fields: [readingId], references: [id], onDelete: Cascade)\n\n  @@index([readingId])\n}\n\nmodel Favorite {\n  id        String   @id @default(cuid())\n  userId    String\n  readingId String\n  createdAt DateTime @default(now())\n\n  User    User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  Reading Reading @relation(fields: [readingId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, readingId])\n  @@index([userId, createdAt])\n}\n\nmodel JournalEntry {\n  id        String   @id @default(cuid())\n  userId    String\n  createdAt DateTime @default(now())\n  title     String?\n  body      String   @db.Text\n\n  User User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId, createdAt])\n}\n",
